VALUES ('xroad.proxy.health-check-port', '2222', 'proxy', '2026-01-01', '2026-01-01');
-- one key configured for two applications: the most recently updated row wins
INSERT INTO configuration_properties (property_key, property_value, scope, created_at, updated_at)
VALUES ('xroad.common-rpc.use-tls', 'false', 'signer', '2026-01-01', '2026-01-01');
INSERT INTO configuration_properties (property_key, property_value, scope, created_at, updated_at)
VALUES ('xroad.common-rpc.use-tls', 'true', 'op-monitor', '2026-02-02', '2026-02-02');
